changeSet.sql:
UPDATE theme SET layout = $J${
  "tiles": {
    "marquee":      { "col": 1,  "row": 1,  "colSpan": 3,  "rowSpan": 28, "orientation": "vertical" },
    "latestDrop":   { "col": 5,  "row": 1,  "colSpan": 10, "rowSpan": 9 },
    "calendar":     { "col": 5,  "row": 11, "colSpan": 10, "rowSpan": 10 },
    "stats":        { "col": 5,  "row": 22, "colSpan": 10, "rowSpan": 7 },
    "identity":     { "col": 16, "row": 1,  "colSpan": 13, "rowSpan": 3,  "hidden": false },
    "today":        { "col": 16, "row": 5,  "colSpan": 13, "rowSpan": 15 },
    "music":        { "col": 16, "row": 21, "colSpan": 13, "rowSpan": 8 },
    "waveSwitcher": { "col": 30, "row": 1,  "colSpan": 5,  "rowSpan": 3 },
    "freshness":    { "col": 36, "row": 1,  "colSpan": 5,  "rowSpan": 3 },
    "sleep":        { "col": 30, "row": 5,  "colSpan": 11, "rowSpan": 5 },
    "photoDrops":   { "col": 30, "row": 11, "colSpan": 5,  "rowSpan": 11, "orientation": "vertical" },
    "ride":         { "col": 36, "row": 11, "colSpan": 5,  "rowSpan": 11 },
    "projects":     { "col": 30, "row": 23, "colSpan": 5,  "rowSpan": 6 },
    "social":       { "col": 36, "row": 23, "colSpan": 5,  "rowSpan": 6 }
  },
  "mobileOrder": ["identity", "today", "music", "calendar", "stats", "sleep", "ride", "latestDrop", "photoDrops", "projects", "social", "marquee", "waveSwitcher", "freshness"]
}$J$::jsonb
WHERE key = 'wave-02';
